\eqalignno{\iint\chi W_n(x,y)\nu(dy)\mu(dx)
&=\int g_nd\mu
=\sup_{G\in\Sigma^f}\int_Gg_n\cr
\displaycause{213B, because $\mu$ is semi-finite}
&=\sup_{G\in\Sigma^f}\lambda(W\cap(G\times Y_n))
=\lambda(W\cap(X\times Y_n))\cr}

