\noalign{\noindent (menurut hipotesis induksi)}
&=\beta_ra^{r+1}I_{r+1}\cr
\noalign{\noindent (menurut (b) di atas)}
&=\beta_{r+1}a^{r+1}\cr}

source_raw_tex:
\eqalign{\beta_r
&=\Bover{1}{k!}\pi^k\text{ if }r=2k\text{ is even},\cr
&=\Bover{2^{2k+1}k!}{(2k+1)!}\pi^k\text{ if }r=2k+1\text{ is odd}.\cr}
